/* Return the value of the smallest odd number in the vector x.
   Examples:

   input: [7, 9, 5, 2, 8, 16, 4, 1]
   output: 1

   input: [8, 36, 7, 2, 11]
   output: 7
*/
int smallestOdd(std::vector<int> const& x) {
    int smallest_odd = std::numeric_limits<int>::max();
    for (const auto& num : x) {
        if (num % 2 == 1) {
            smallest_odd = std::min(smallest_odd, num);
        }
    }
    return smallest_odd;
}

