    std::vector<double> coefficients(input.size(), 1.0 / 3.0);
    for (size_t i = 0; i < input.size(); i++) {
        if (i > 0) {
            coefficients[i] += 1.0 / 3.0;
        }
        if (i < input.size() - 1) {
            coefficients[i] += 1.0 / 3.0;
        }
    }

    // Compute the output using precomputed coefficients
    for (size_t i = 0; i < input.size(); i++) {
        double sum = 0.0;
        if (i > 0) {
            sum += input[i - 1];
        }
        if (i < input.size() - 1) {
            sum += input[i + 1];
        }
        sum += input[i];
        output[i] = sum * coefficients[i];
    }
